import { useState } from 'react';
import { View } from 'react-native';
import type { Location, PlatformBusiness } from '@inventory/contracts';
import { Action } from '../ui/Controls';
import { Text } from '../ui/Themed';
import { SidePanel } from '../ui/SidePanel';
import { StatusBadge } from '../ui/StatusBadge';
import { useTheme } from '../theme';
import { BusinessLocations } from './BusinessLocations';
export function BusinessDirectory({
  items,
  grid,
  onManage,
}: {
  items: PlatformBusiness[];
  grid: boolean;
  onManage?: (businessId: string, location: boolean) => void;
}) {
  const theme = useTheme(),
    [expanded, setExpanded] = useState<string[]>([]),
    [selected, setSelected] = useState<{ business: PlatformBusiness; location?: Location } | null>(
      null,
    );
  return (
    <>
      <View
        style={{
          flexDirection: grid ? 'row' : 'column',
          flexWrap: 'wrap',
          gap: theme.spacing.small,
        }}
      >
        {items.map((business) => (
          <View
            key={business.id}
            style={{
              width: grid ? '47%' : '100%',
              flexGrow: 1,
              padding: theme.spacing.medium,
              borderRadius: theme.radius,
              backgroundColor: theme.colors.card,
              gap: theme.spacing.small,
            }}
          >
            <Action
              label={business.name}
              variant="ghost"
              onPress={() => setSelected({ business })}
            />
            <StatusBadge
              label={business.state}
              tone={business.state === 'active' ? 'success' : 'warning'}
            />
            <Text>{business.createdAt.slice(0, 10)} UTC</Text>
            <Text tone="muted">
              {business.storeCount ?? '—'} stores · {business.warehouseCount ?? '—'} warehouses
            </Text>
            <Action
              variant="ghost"
              label={
                grid
                  ? `View locations for ${business.name}`
                  : `${expanded.includes(business.id) ? '⌄ Hide' : '› Show'} stores & warehouses for ${business.name}`
              }
              onPress={() =>
                grid
                  ? setSelected({ business })
                  : setExpanded((old) =>
                      old.includes(business.id)
                        ? old.filter((id) => id !== business.id)
                        : [...old, business.id],
                    )
              }
            />
            {!grid && expanded.includes(business.id) && (
              <BusinessLocations
                business={business}
                onOpen={(location) => setSelected({ business, location })}
              />
            )}
          </View>
        ))}
      </View>
      <SidePanel
        title={selected?.location ? 'Location details' : 'Business details'}
        open={!!selected}
        onClose={() => setSelected(null)}
      >
        {selected && (
          <>
            {onManage && (
              <Action
                label="Manage in business workspace"
                onPress={() => onManage?.(selected.business.id, !!selected.location)}
              />
            )}
            <Text accessibilityRole="header">
              {selected.location?.name ?? selected.business.name}
            </Text>
            <Text>Status: {selected.location?.state ?? selected.business.state}</Text>
            <Text>Business: {selected.business.name}</Text>
            <Text>Time zone: {selected.business.timeZone}</Text>
            {selected.location ? (
              <>
                <Text>Code: {selected.location.code}</Text>
                <Text>Type: {selected.location.type}</Text>
                <Text>Store reference: {selected.location.storeId ?? 'This is a store'}</Text>
              </>
            ) : (
              <>
                <Text>Registered (UTC): {selected.business.createdAt}</Text>
                {grid && (
                  <BusinessLocations
                    business={selected.business}
                    grid
                    onOpen={(location) => setSelected({ ...selected, location })}
                  />
                )}
              </>
            )}
          </>
        )}
      </SidePanel>
    </>
  );
}

import { BusinessLocationCards } from './BusinessLocationCards';
import { useEffect, useMemo, useState, useSyncExternalStore } from 'react';
import { View } from 'react-native';
import { createPlatformBusinessesClient, cancellableResource } from '@inventory/api-client';
import type { Location, PlatformBusiness } from '@inventory/contracts';
import { authClient } from '../auth/client';
import { Action } from '../ui/Controls';
import { Text } from '../ui/Themed';
import { Pagination } from '../ui/Pagination';
import { usePageCollection } from '../ui/usePageCollection';
import { useTheme } from '../theme';
export function BusinessLocations({
  business,
  onOpen,
  grid = false,
}: {
  business: PlatformBusiness;
  grid?: boolean;
  onOpen: (location: Location) => void;
}) {
  const theme = useTheme(),
    [offset, setOffset] = useState(0);
  const request = useMemo(
    () =>
      cancellableResource(
        (signal) =>
          createPlatformBusinessesClient(authClient.accountRequest).detail(
            business.id,
            offset,
            signal,
          ),
        () => new AbortController(),
      ),
    [business.id, offset],
  );
  const raw = useSyncExternalStore(request.model.subscribe, request.model.snapshot);
  const state = usePageCollection(raw, [business.id], offset, ['locations'], () => setOffset(0));
  useEffect(() => {
    void request.model.run();
    return request.cancel;
  }, [request]);
  return (
    <View style={{ gap: theme.spacing.small }}>
      <Text accessibilityRole="header">Stores &amp; warehouses</Text>
      {state.busy && <Text accessibilityLiveRegion="polite">Loading locations…</Text>}
      {!!state.error && (
        <>
          <Text accessibilityRole="alert">{state.error}</Text>
          <Action label="Retry locations" onPress={() => void request.model.run()} />
        </>
      )}
      {state.data && !state.data.locations.length && (
        <Text>No registered stores or warehouses.</Text>
      )}
      {grid && state.data ? (
        <BusinessLocationCards locations={state.data.locations} onOpen={onOpen} />
      ) : (
        state.data?.locations.map((location) => (
          <View
            key={location.id}
            style={{
              padding: theme.spacing.small,
              backgroundColor: theme.tokens.secondary,
              borderRadius: theme.radius,
            }}
          >
            <Action variant="ghost" label={location.name} onPress={() => onOpen(location)} />
            <Text>
              {location.code} · {location.kind} · {location.state}
            </Text>
          </View>
        ))
      )}
      <Pagination
        label={`locations for ${business.name}`}
        offset={offset}
        hasMore={state.data?.hasMore ?? false}
        busy={state.busy}
        onChange={setOffset}
      />
    </View>
  );
}

import { View } from 'react-native';
import type { Location } from '@inventory/contracts';
import { useTheme } from '../theme';
import { Text } from '../ui/Themed';
import { Action } from '../ui/Controls';
import { StatusBadge } from '../ui/StatusBadge';
export function BusinessLocationCards({
  locations,
  onOpen,
}: {
  locations: Location[];
  onOpen: (location: Location) => void;
}) {
  const theme = useTheme();
  return (
    <View style={{ gap: theme.spacing.large }}>
      {(['stores', 'warehouses'] as const).map((kind) => {
        const items = locations.filter((location) => location.kind === kind);
        if (!items.length) return null;
        return (
          <View key={kind} style={{ gap: theme.spacing.small }}>
            <Text accessibilityRole="header">
              {kind === 'stores' ? 'Stores & branches' : 'Warehouses'}
            </Text>
            {items.map((location) => (
              <View
                key={location.id}
                style={{
                  padding: theme.spacing.medium,
                  gap: theme.spacing.small,
                  borderRadius: theme.radius,
                  backgroundColor: theme.tokens.secondary,
                  borderWidth: parseFloat(theme.tokens['border-width']),
                  borderColor: theme.tokens.border,
                }}
              >
                <Text tone="muted">
                  {location.type === 'branch'
                    ? 'Branch'
                    : kind === 'stores'
                      ? 'Store'
                      : 'Warehouse'}{' '}
                  · {location.code}
                </Text>
                <Action label={location.name} variant="ghost" onPress={() => onOpen(location)} />
                <StatusBadge
                  label={location.state}
                  tone={location.state === 'active' ? 'success' : 'warning'}
                />
              </View>
            ))}
          </View>
        );
      })}
    </View>
  );
}

