          <RegistrationTrend rows={data.registrations} />
          <Action
            label="View administrative logs"
            variant="ghost"
            onPress={() => navigate('/logs')}
          />
          <Action label="↗ View all businesses" onPress={() => navigate('/admin/businesses')} />
        </>
      )}
    </View>
  );
}

